package invoice;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.math.BigDecimal;
import java.util.*;
import java.util.List;
import com.fasterxml.jackson.databind.JsonNode;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.*;

/** Detect ruled cells from pixels and assign positioned PDF/OCR text to those cells. */
public final class TableGrid {
 public static final String VERSION="border-grid-v1";
 public record Box(String text,double x,double y,double width,double height,boolean glyph) {double cx(){return x+width/2;}double cy(){return y+height/2;}}
 record Stroke(int at,int start,int end){}
 public record Grid(List<Integer> x,List<Integer> y){public Rectangle bounds(){return new Rectangle(x.get(0),y.get(0),x.get(x.size()-1)-x.get(0),y.get(y.size()-1)-y.get(0));}}
 public record Result(List<Map<String,String>> items,List<Map<String,Object>> evidence,boolean complete){}
 public static List<Grid> detect(BufferedImage image){
  int width=image.getWidth(),height=image.getHeight();if(width<150||height<100||(long)width*height>24_000_000)return List.of();
  boolean[] ink=new boolean[width*height];int[] pixels=image.getRGB(0,0,width,height,null,0,width);for(int i=0;i<pixels.length;i++){int p=pixels[i];ink[i]=((p>>>24)&255)>40&&Math.min((p>>>16)&255,Math.min((p>>>8)&255,p&255))<185;}
  List<Stroke> horizontal=strokes(ink,width,height,true,Math.max(80,width/4)),vertical=strokes(ink,width,height,false,Math.max(35,height/30));List<Grid> result=new ArrayList<>();
  for(Stroke seed:vertical){List<Stroke> group=vertical.stream().filter(v->Math.abs(v.start-seed.start)<=5&&Math.min(v.end,seed.end)-Math.max(v.start,seed.start)>Math.min(v.end-v.start,seed.end-seed.start)*.65).sorted(Comparator.comparingInt(Stroke::at)).toList();if(group.size()<4)continue;
   List<Integer> xs=distinct(group.stream().map(Stroke::at).toList(),4);int left=xs.get(0),right=xs.get(xs.size()-1),top=group.stream().mapToInt(Stroke::start).min().orElse(0),bottom=group.stream().mapToInt(Stroke::end).max().orElse(0);if(right-left<width*.4)continue;
   List<Integer> ys=distinct(horizontal.stream().filter(h->h.at>=top-5&&h.at<=bottom+5&&h.start<=left+6&&h.end>=right-6).map(Stroke::at).sorted().toList(),4);if(ys.size()<3)continue;Grid grid=new Grid(xs,ys);Rectangle bounds=grid.bounds();if(result.stream().noneMatch(old->overlap(old.bounds(),bounds)>.8))result.add(grid);
  }result.sort(Comparator.comparingInt(g->g.y.get(0)));return result;
 }
 static double overlap(Rectangle a,Rectangle b){Rectangle intersection=a.intersection(b);return intersection.isEmpty()?0:(double)intersection.width*intersection.height/Math.min((long)a.width*a.height,(long)b.width*b.height);}
 static List<Integer> distinct(List<Integer> values,int tolerance){List<Integer> out=new ArrayList<>();for(int value:values)if(out.isEmpty()||value-out.get(out.size()-1)>tolerance)out.add(value);return out;}
 static List<Stroke> strokes(boolean[] ink,int width,int height,boolean horizontal,int minimum){int outer=horizontal?height:width,inner=horizontal?width:height,gap=Math.max(2,width/500);List<Stroke> raw=new ArrayList<>();for(int at=0;at<outer;at++){int start=-1,last=-1,count=0;for(int along=0;along<=inner+gap;along++){boolean dark=along<inner&&ink[horizontal?at*width+along:along*width+at];if(dark){if(start<0)start=along;last=along;count++;}else if(start>=0&&along-last>gap){if(last-start>=minimum&&count>=(last-start)*.42)raw.add(new Stroke(at,start,last));start=-1;count=0;}}}
  List<Stroke> merged=new ArrayList<>();boolean[] used=new boolean[raw.size()];for(int i=0;i<raw.size();i++){if(used[i])continue;Stroke first=raw.get(i);int lastAt=first.at,start=first.start,end=first.end,count=1;used[i]=true;for(int j=i+1;j<raw.size()&&raw.get(j).at<=lastAt+1;j++){Stroke next=raw.get(j);if(!used[j]&&Math.abs(next.start-start)<8&&Math.abs(next.end-end)<8){used[j]=true;lastAt=next.at;start=Math.min(start,next.start);end=Math.max(end,next.end);count++;}}if(lastAt-first.at<=Math.max(4,width/350))merged.add(new Stroke((first.at+lastAt)/2,start,end));}return merged;
 }
 public static List<Box> pdfWords(PDDocument document,int page,BufferedImage image)throws IOException{
  var pdPage=document.getPage(page);if(pdPage.getRotation()!=0)return List.of();double sx=image.getWidth()/pdPage.getCropBox().getWidth(),sy=image.getHeight()/pdPage.getCropBox().getHeight();List<Box> boxes=new ArrayList<>();
  PDFTextStripper stripper=new PDFTextStripper(){@Override protected void processTextPosition(TextPosition p){String text=p.getUnicode();if(text!=null&&!text.isBlank())boxes.add(new Box(text,p.getXDirAdj()*sx,(p.getYDirAdj()-p.getHeightDir())*sy,p.getWidthDirAdj()*sx,p.getHeightDir()*sy,true));}};stripper.setStartPage(page+1);stripper.setEndPage(page+1);stripper.getText(document);return boxes;
 }
 public static List<Box> visionWords(JsonNode response,int width,int height,int offsetX,int offsetY){List<Box> result=new ArrayList<>();var annotation=response.path("responses").path(0);var page=annotation.path("fullTextAnnotation").path("pages").path(0);double sx=width/Math.max(1,page.path("width").asDouble(width)),sy=height/Math.max(1,page.path("height").asDouble(height));var words=annotation.path("textAnnotations");for(int i=1;i<words.size();i++){var word=words.path(i);double left=Double.MAX_VALUE,top=Double.MAX_VALUE,right=0,bottom=0;for(var vertex:word.path("boundingPoly").path("vertices")){double x=vertex.path("x").asDouble(),y=vertex.path("y").asDouble();left=Math.min(left,x);top=Math.min(top,y);right=Math.max(right,x);bottom=Math.max(bottom,y);}if(left!=Double.MAX_VALUE)result.add(new Box(word.path("description").asText(),offsetX+left*sx,offsetY+top*sy,(right-left)*sx,(bottom-top)*sy,false));}return result;}
 static String cell(List<Box> words,int left,int top,int right,int bottom){List<Box> sorted=words.stream().filter(w->w.cx()>left&&w.cx()<right&&w.cy()>top&&w.cy()<bottom).sorted(Comparator.comparingDouble(Box::cy)).toList();List<List<Box>> lines=new ArrayList<>();for(Box box:sorted){if(lines.isEmpty()||Math.abs(box.cy()-lines.get(lines.size()-1).get(0).cy())>Math.max(3,box.height*.6))lines.add(new ArrayList<>());lines.get(lines.size()-1).add(box);}StringBuilder result=new StringBuilder();for(List<Box> line:lines){line.sort(Comparator.comparingDouble(Box::x));Box previous=null;if(!result.isEmpty())result.append(' ');for(Box box:line){if(previous!=null&&( !box.glyph||box.x-(previous.x+previous.width)>Math.max(1,box.height*.18)))result.append(' ');result.append(box.text);previous=box;}}return result.toString().trim().replaceAll("\\s+"," ");}
 static String header(String value){String text=Parser.fold(value).replaceAll("\\s+"," ");if(text.contains("unit price")||text.contains("don gia"))return "unitPrice";if(text.contains("thanh tien")||text.contains("amount"))return "amount";if(text.contains("so luong")||text.contains("quantity"))return "quantity";if(text.contains("don vi tinh")||text.matches(".*\\bunit\\b.*"))return "unit";if(text.contains("ten hang")||text.contains("description")||text.contains("ten san pham"))return "description";if(text.contains("stt")||text.matches(".*\\bno\\.?\\b.*"))return "line";if(text.contains("hs code")||text.equals("hs"))return "hsCode";if(text.contains("ma nvl")||text.contains("material code")||text.contains("ma hang"))return "materialCode";return "";}
 static boolean footer(String text){String folded=Parser.fold(text);return folded.contains("cong tien hang")||folded.contains("tong cong")||folded.contains("tien thue")||folded.contains("thanh toan")||folded.contains("subtotal")||folded.contains("grand total");}
 static String numeric(String text,String document){String value=text.replaceAll("\\s","").replace('−','-');if(value.isBlank())return "";return Parser.number(value,document).toPlainString();}
 public static Result extract(List<Grid> grids,List<Box> words,String document,int page,int width,int height){List<Map<String,String>> items=new ArrayList<>();List<Map<String,Object>> evidence=new ArrayList<>();boolean complete=true;
  for(Grid grid:grids){Map<Integer,String> mapping=new LinkedHashMap<>();int headerRow=-1;for(int row=0;row<Math.min(4,grid.y.size()-1);row++){Map<Integer,String> candidate=new LinkedHashMap<>();for(int col=0;col<grid.x.size()-1;col++){String key=header(cell(words,grid.x.get(col),grid.y.get(row),grid.x.get(col+1),grid.y.get(row+1)));if(!key.isBlank())candidate.put(col,key);}if(candidate.containsValue("description")&&candidate.containsValue("quantity")&&candidate.containsValue("amount")){mapping=candidate;headerRow=row;break;}}if(headerRow<0)continue;
   int startCount=items.size();for(int row=headerRow+1;row<grid.y.size()-1;row++){Map<String,String> cells=new LinkedHashMap<>();for(var entry:mapping.entrySet())cells.put(entry.getValue(),cell(words,grid.x.get(entry.getKey()),grid.y.get(row),grid.x.get(entry.getKey()+1),grid.y.get(row+1)));String desc=cells.getOrDefault("description","");if(footer(String.join(" ",cells.values())))break;if(!desc.matches(".*\\p{L}.*"))continue;String line=cells.getOrDefault("line","");if(mapping.containsValue("line")&&!line.matches("\\d{1,4}")){if(!items.isEmpty()&&cells.getOrDefault("amount","").isBlank()&&cells.getOrDefault("quantity","").isBlank()){Map<String,String> prior=items.get(items.size()-1);prior.put("description",prior.get("description")+" "+desc);continue;}complete=false;}
    Map<String,String> item=new LinkedHashMap<>();for(String key:List.of("line","description","unit","hsCode","materialCode"))item.put(key,cells.getOrDefault(key,""));if(item.get("line").isBlank())item.put("line",String.valueOf(items.size()+1));for(String key:List.of("quantity","unitPrice","amount"))try{item.put(key,numeric(cells.getOrDefault(key,""),document));}catch(Exception ex){item.put(key,"");complete=false;}if(item.get("quantity").isBlank()||item.get("amount").isBlank())complete=false;
    item.put("page",String.valueOf(page));item.put("tableBounds",grid.bounds().x+","+grid.bounds().y+","+grid.bounds().width+","+grid.bounds().height);item.put("rowBounds",grid.y.get(row)+","+grid.y.get(row+1));items.add(item);
   }
   if(items.size()>startCount){Map<String,Object> table=new LinkedHashMap<>();table.put("version",VERSION);table.put("page",page);table.put("headers",mapping);table.put("columns",grid.x.stream().map(x->(double)x/width).toList());table.put("rows",grid.y.stream().map(y->(double)y/height).toList());table.put("itemCount",items.size()-startCount);evidence.add(table);}
  }return new Result(items,evidence,complete&&!items.isEmpty());
 }
 public static Rectangle crop(Grid grid,BufferedImage image){Rectangle b=grid.bounds();int left=Math.max(0,b.x-12),top=Math.max(0,b.y-12);return new Rectangle(left,top,Math.min(image.getWidth(),b.x+b.width+12)-left,Math.min(image.getHeight(),b.y+b.height+12)-top);}
 public static boolean amountsMatch(List<Map<String,String>> items,String subtotal){try{return items.stream().map(i->new BigDecimal(i.get("amount"))).reduce(BigDecimal.ZERO,BigDecimal::add).subtract(new BigDecimal(subtotal)).abs().compareTo(BigDecimal.ONE)<=0;}catch(Exception e){return false;}}
}
